#include <stdio.h>

void processArray(int *arr, int size) {
    for (int i = 0; i < size; i++) {
        arr[i] *= 2;
    }
}

int main(void) {
    int arr[] = {1, 2, 3, 4, 5};
    processArray(arr + 2, 3);
    printf("%d %d\n", arr[1], arr[3]);
    return 0;
}

#include <iostream>

void increase(int& value) {
    value += 1;
}

int main() {
    int n = 3;
    increase(n);
    std::cout << n << "\n";
    return 0;
}

class Animal {
    String sound() {
        return "animal";
    }
}

class Dog extends Animal {
    @Override
    String sound() {
        return "woof";
    }
}

public class Main {
    public static void main(String[] args) {
        Animal animal = new Dog();
        System.out.println(animal.sound());
    }
}

CREATE TABLE students (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE scores (
  student_id TEXT REFERENCES students(id),
  course TEXT, score INTEGER,
  PRIMARY KEY (student_id, course)
);
INSERT INTO students VALUES ('S1', '小林'), ('S2', '小陳'), ('S3', '小王');
INSERT INTO scores VALUES ('S1', '國文', 80), ('S1', '英文', 50), ('S2', '國文', 90);

SELECT s.id, s.name, COUNT(g.course) AS passed
FROM students AS s
LEFT JOIN scores AS g
  ON g.student_id = s.id AND g.score >= 60
GROUP BY s.id, s.name
ORDER BY s.id;

